    // Toggle info blocks
    function setInfoOpen(btn, open) {
        btn.closest(".info-block").classList.toggle("open", open);
        btn.classList.toggle("active", open);
        btn.setAttribute("aria-expanded", String(open));
    }

    document.querySelectorAll(".info-toggle").forEach((btn, index) => {
        const content = btn.nextElementSibling;
        if (!content || !content.classList.contains("info-content")) return;
        content.id ||= `info-content-${index + 1}`;
        btn.type = "button";
        btn.setAttribute("aria-controls", content.id);
        setInfoOpen(btn, btn.closest(".info-block").classList.contains("open"));
        btn.addEventListener("click", () => {
            setInfoOpen(btn, btn.getAttribute("aria-expanded") !== "true");
        });
    });

    // Открытие блока по якорной ссылке в URL (например #certificates)
    function openBlockByHash() {
        const hash = window.location.hash;
        if (hash) {
            const block = document.getElementById(hash.slice(1));
            if (block && block.classList.contains("info-block")) {
                const btn = block.querySelector(".info-toggle");
                const content = block.querySelector(".info-content");
                if (btn && content) {
                    setInfoOpen(btn, true);
                }
                setTimeout(() => {
                    block.scrollIntoView({ behavior: "smooth", block: "center" });
                }, 300);
            }
        }
    }
